import { useState, useEffect } from 'react';
import { Table, Button, Alert } from 'react-bootstrap';
import { useSearchParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

interface Game {
  id: number;
  status: string;
  maps: { id: number; name: string }[];
}

const GameConstructor = () => {
  const [searchParams] = useSearchParams();
  const gameId = searchParams.get('game');
  const [game, setGame] = useState<Game | null>(null);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    if (gameId) {
      axios
        .get(`/api/games/${gameId}`, { withCredentials: true })
        .then(res => setGame(res.data))
        .catch(err => {
          if (err.response?.status === 401 || err.response?.status === 403) {
            navigate('/login', { replace: true });
          } else {
            setError('Failed to load game. Please try again.');
            console.error(err);
          }
        });
    }
  }, [gameId, navigate]);

  if (!game) return <div>{error || 'Loading...'}</div>;

  return (
    <div>
      {error && <Alert variant="danger">{error}</Alert>}
      <h2>Game Constructor (Status: {game.status})</h2>
      <Table striped bordered hover>
        <thead>
          <tr>
            <th>Map</th>
            {game.status === 'draft' && <th>Actions</th>}
          </tr>
        </thead>
        <tbody>
          {game.maps.map(map => (
            <tr key={map.id}>
              <td>{map.name}</td>
              {game.status === 'draft' && (
                <td>
                  <Button
                    variant="danger"
                    onClick={() =>
                      axios
                        .delete(`/api/games/${game.id}/remove-map/${map.id}`, { withCredentials: true })
                        .then(() => {
                          setGame({
                            ...game,
                            maps: game.maps.filter(m => m.id !== map.id),
                          });
                        })
                        .catch(() => setError('Failed to remove map. Please try again.'))
                    }
                  >
                    Remove
                  </Button>
                </td>
              )}
            </tr>
          ))}
        </tbody>
      </Table>
      {game.status === 'draft' && (
        <Button
          onClick={() =>
            axios
              .put(`/api/games/form/${game.id}`, {}, { withCredentials: true })
              .then(() => navigate('/games'))
              .catch(() => setError('Failed to form game. Please try again.'))
          }
        >
          Form Game
        </Button>
      )}
      <Button onClick={() => navigate('/games')}>Back to Games</Button>
    </div>
  );
};

export default GameConstructor;
